/**
 * 企业侧归档一条 —— 求职端 归档条（数据/类型.ts）的镜像，字段一一对应：
 * 公司/公司首字 → 代号/头像字（双盲：意向确认前企业侧也只留代号，不落真名），
 * 职位那一栏落岗位名，好在一屏里区分「同一位候选在哪个岗上被终止的」。
 * 编号 = 候选编号，归档卡按它回看 企业往来记录。
 */
export interface 企业归档条 {
  编号: string;
  代号: string;
  头像字: string;
  画像: string;
  岗位编号: string;
  职位: string;
  止步阶段: 阶段;
  /** 企业侧目前只有「你按下终止」这一条归档路径，先只列它，不预留用不上的分支 */
  结果: '我方终止';
  原因: string;
  时间: string;
}

export interface 状态 extends 候选资料状态, 组织岗位状态, 隐私设置状态,
  发现推荐状态, MatchCase状态, Agent规则状态, 消息状态 {
  子视图: 子视图;
  当前Tab: 底部Tab;
  企业子视图: '在谈' | '推荐';
  企业Tab: '人才' | '消息' | '我的';
  /** 当前页面资料已从哪个账号仓水合；写入前必须与当前主体一致。 */
  资料缓存范围键: string;
}

export type 动作 =
  // ── 七个按 owner 拆出的域 action ──
  | 候选资料动作
  | 组织岗位动作
  | 隐私设置动作
  | 发现推荐动作
  | MatchCase动作
  | Agent规则动作
  | 消息动作
  // ── 保留在根的动作：导航 / Tab / 身份视图 + 跨域编排（发布岗位 / 委托入谈 / 接触推荐候选 /
  //    切意向 / 切当前岗位 / 看全部在谈 / 企业看全部在谈），逐字保留 ──
  | { 型: '切意向'; 意向: string; /** Backend 顶栏随胶囊带上的 intention_id 编号载体；Mock 不传 */ 编号?: string }
  | { 型: '切子视图'; 子视图: 子视图 }
  | { 型: '切Tab'; Tab: 底部Tab }
  /** 「我的」的统计数字点进来：切到职位 Tab 的在谈列表，范围置全部，并落到指定档 */
  | { 型: '看全部在谈'; 档: 看什么档 }
  | { 型: '委托入谈'; 岗: 市场职位 }
  // ── 企业端动作 ──
  | { 型: '企业切Tab'; Tab: '人才' | '消息' | '我的' }
  | { 型: '企业切子视图'; 子视图: '在谈' | '推荐' }
  | { 型: '切当前岗位'; 编号: string }
  /** 企业「我的」的统计数字点进来：切到人才 Tab 的在谈列表，范围置全部岗位，并落到指定档 */
  | { 型: '企业看全部在谈'; 档: 看什么档 }
  | { 型: '接触推荐候选'; 编号: string }
  | { 型: '发布岗位'; 岗: 在招岗位 }
  | { 型: '水合账号资料'; 范围键: string; 快照: 资料缓存快照 }
  | { 型: '清账号资料' }
  // Backend MatchCase 真相源修复：只供 Backend 会话边界（登出 / 当前轮 401 / 主体基串
  // 变化）原子清空四个 legacy 演示数组；Mock 初始化与普通 Mock reducer 不派发它
  | { 型: '清后端MatchCase演示状态' }
  | { 型: '切身份'; 到: '求职者' | '招聘方' };

export function 数未读(表: Record<string, number>): number {
  return Object.values(表).reduce((和, 数) => 和 + (数 > 0 ? 数 : 1), 0);
}

export function 归约(旧: 状态, 动作: 动作): 状态 {
  switch (动作.型) {
    // ── 七个按 owner 拆出的域 reducer：逐项列出 case，不使用字符串 registry / 数组 includes ──
    case '改意向':
    case '删意向':
    case '新增意向':
    case '开意向草稿':
    case '改意向草稿':
    case '清意向草稿':
    case '存简历':
    case '存个人优势':
    case '存作品集链接':
    case '存简历文件名':
    case '存求职头像':
    case '存联系方式':
    case '存引导预填':
    case '启程引导':
    case '存求职筛选偏好':
    case '存薪资预填':
    case '存到岗预填':
    case '水合后端简历':
    case '水合后端意向':
    case '水合候选引导草稿':
    case '清后端草稿':
      return 归约候选资料(旧, 动作);

    case '更新岗位':
    case '停止招聘':
    case '重开岗位':
    case '删除岗位':
    case '水合后端岗位':
    case '存公司自述':
    case '存企业认证':
    case '存招聘头像':
    case '存公司LOGO':
    case '水合招聘方档案':
    case '水合企业关系':
    case '选择当前企业关系':
    case '水合企业管理员申请':
    case '水合当前企业':
    case '缓存公开企业':
    case '标记公开企业不可用':
    case '存未认证公司声明':
    case '清后端组织状态':
      return 归约组织岗位(旧, 动作);

    case '拉黑':
    case '水合后端隐私':
    case '清后端隐私':
    case '解除屏蔽':
    case '设披露档':
    case '设企业披露档':
    case '切设置开关':
    case '企业切设置开关':
    case '设飞书接入':
    case '设企业飞书接入':
      return 归约隐私设置(旧, 动作);

    case '委托代理':
    case '不感兴趣':
    case '切收藏候选':
    case '标记不合适':
    case '撤销不合适':
    case '补给推荐':
      return 归约发现推荐(旧, 动作);

    case '设在谈看什么':
    case '设在谈范围':
    case '企业设在谈看什么':
    case '企业设在谈范围':
    case '接受方案':
    case '退出谈判':
    case '确认意向':
    case '候选接受方案':
    case '候选终止':
    case '候选确认意向':
    case '加叮嘱':
      return 归约MatchCase(旧, 动作);

    case '新增规则':
    case '改规则':
    case '删规则':
    case '切规则开关':
    case '企业新增规则':
    case '企业改规则':
    case '企业删规则':
    case '企业切规则开关':
    case '设先问偏好':
    // P6：Backend 水合/清空也在 Agent 规则域；不在 reducer 里判模式，操作/会话层拥有边界
    case '水合后端候选规则':
    case '水合后端招聘规则':
    case '清后端Agent规则':
      return 归约Agent规则(旧, 动作);

    case '读消息':
    case '企业读消息':
      return 归约消息(旧, 动作);

    // ── 保留在根的跨域编排 / 导航 / Tab / 身份视图 ──
    // 顶栏点某条意向 = 明确说了「我要看这一条」，范围跟着收回当前 ——
    // 否则处在「全部意向」档时点胶囊会毫无反应（列表照旧全量），顶栏看起来是坏的
    case '切意向':
      // Backend 随 action 带上的编号载体是 P4 发现域的唯一 scope 坐标；
      // 不带（Mock 全部路径）就归 null —— 编号载体在 Mock 里恒空、无人读。
      return { ...旧, 当前意向: 动作.意向, 当前意向编号: 动作.编号 ?? null, 在谈范围: '当前' };
    case '切子视图':
      return { ...旧, 子视图: 动作.子视图 };
    case '切Tab':
      return { ...旧, 当前Tab: 动作.Tab };

    // 「我的」的统计数字读的是全量在谈，所以点它落地的列表也必须是全量：
    // 统计写 8、点进去只有 5，正是拦路 6 那个「少的 3 个去哪了」
    case '看全部在谈':
      return { ...旧, 当前Tab: '职位', 子视图: '在谈', 在谈范围: '全部', 在谈看什么: 动作.档 };

    // 标注意见 #8：「让AI代理去谈」把市场岗位真的变成一个在谈单 ——
    // 代理立刻主动打招呼（打招呼内容在详情/往来记录里可见），阶段从匿名初筛起步。
    // 同时写 发现推荐.已委托 与 MatchCase.在谈列表，保留在根跨域编排。
    case '委托入谈': {
      if (旧.在谈列表.some((条) => 条.编号 === 动作.岗.编号)) return 旧; // 幂等
      // 市场岗与在谈单现在字段同名同义，直接搬 —— 卡片上半截一个像素都不变，
      // 只是底下多长出「阶段 + 下一步」那一段
      const 新单: 在谈单 = {
        编号: 动作.岗.编号,
        意向: 动作.岗.意向,
        公司: 动作.岗.公司,
        公司首字: 动作.岗.公司首字,
        公司简介: 动作.岗.公司简介,
        薪资: 动作.岗.薪资,
        职位: 动作.岗.职位,
        标签: 动作.岗.标签,
        阶段: '匿名初筛',
        轮次: '第 1 轮',
        下一步: 'AI代理已主动发起接触，等待对方响应',
        辅助文案: '硬性条件核对中，无需你介入',
        需要你: false,
        分歧: null,
        适配分: 动作.岗.适配分,
      };
      return {
        ...旧,
        已委托: 旧.已委托.includes(动作.岗.编号) ? 旧.已委托 : [...旧.已委托, 动作.岗.编号],
        在谈列表: [...旧.在谈列表, 新单],
      };
    }

    // ── 企业端动作：与求职端同构的镜像逻辑 ──
    case '企业切Tab':
      return { ...旧, 企业Tab: 动作.Tab };
    case '企业切子视图':
      return { ...旧, 企业子视图: 动作.子视图 };
    // 点某个岗位胶囊 = 明确说了「我要看这个岗」，范围跟着收回当前（同 切意向）
    case '切当前岗位':
      return { ...旧, 当前岗位编号: 动作.编号, 企业在谈范围: '当前' };

    // 企业「我的」的「待拍板」算的是跨岗位的数，落地的列表也必须跨岗位 ——
    // 否则招聘方看到 3、点进去只有本岗的 1，剩下 2 个要自己逐岗切顶栏找（拦路 5）
    case '企业看全部在谈':
      return {
        ...旧,
        企业Tab: '人才',
        企业子视图: '在谈',
        企业在谈范围: '全部',
        企业在谈看什么: 动作.档,
      };

    // P1C：快照里的 当前企业关系编号 未经最新 affiliations 校验，必须丢弃；
    // 该编号只能经 水合企业关系 或 可用企业关系() 校验后的 选择当前企业关系 写入。
    case '水合账号资料': {
      const { 当前企业关系编号: _未校验编号, ...已校验账号资料 } = 动作.快照;
      return { ...旧, ...已校验账号资料, 资料缓存范围键: 动作.范围键 };
    }
    case '清账号资料':
      return { ...旧, ...空账号资料, 资料缓存范围键: '' };

    // Backend 会话边界的 legacy Case 状态归零（spec §A）：清空后的数组长度 0 不得被
    // 任何 Backend 展示读成统计事实；Mock 路径永不触达这个 case
    case '清后端MatchCase演示状态':
      return {
        ...旧,
        在谈列表: [],
        企业候选列表: [],
        归档列表: [],
        企业归档列表: [],
      };

    // 让AI代理去聊（标注 2026-08-18 17:42）：这位候选真的进「在谈」列表，
    // 并把子视图切到在谈让用户看到 —— 镜像求职端「委托入谈」的闭环。
    // 同时写 发现推荐.已接触推荐 与 MatchCase.企业候选列表，保留在根跨域编排。
    case '接触推荐候选': {
      if (旧.已接触推荐.includes(动作.编号)) return 旧; // 幂等
      const 推 = 旧.推荐列表.find((条) => 条.编号 === 动作.编号);
      const 新候选: 候选 | null = 推
        ? {
            编号: 推.编号,
            岗位编号: 推.岗位编号,
            代号: 推.代号,
            画像: 推.画像,
            真名: null,
            头像字: 推.头像字,
            阶段: '匿名初筛',
            轮次: '第 1 轮',
            下一步: 'AI代理已主动发起接触，等待对方代理响应',
            辅助文案: '硬性条件核对中，无需你介入',
            需要你: false,
            分歧: null,
            匹配分: 推.匹配分,
          }
        : null;
      // 标注 2026-08-19 11:52：不跳走 —— 代理自己去谈，用户留在推荐页继续挑；
      // 这个人已经进在谈了，下次打开推荐页不该再出现（由列表按 已接触推荐 过滤）
      return {
        ...旧,
        已接触推荐: [...旧.已接触推荐, 动作.编号],
        企业候选列表: 新候选 ? [...旧.企业候选列表, 新候选] : 旧.企业候选列表,
      };
    }

    // 新发布的岗位插到列表最前并自动选中（标注意见 2026-08-18）——
    // 用户刚填完就想看见它，排在第 3 个还要自己找。
    // 同时写 组织岗位.岗位列表/当前岗位编号、发现推荐.推荐列表、MatchCase.企业候选列表 +
    // 导航落点，保留在根跨域编排。
    case '发布岗位': {
      const 新编号 = 动作.岗.编号;
      // 在谈数 已退役（拦路 11）：这个静态字段没有任何屏再读它，岗位管理行内与删除守卫
      // 一律实时数 企业候选列表。原来这里硬编码 2，刚发布的岗位就顶着一个看起来像真的假数字；
      // 真实的 2 由下面那两名起步候选进 企业候选列表 后被实时算出来。
      // 字段本身暂时留着：类型.ts / 企业端模拟数据.ts / 发布岗位.tsx 还在写它，
      // 删字段要一起改那三个文件，不在本轮范围内。写 0 = 明示「这里不再是数据源」
      const 新岗: 在招岗位 = { ...动作.岗, 状态: '在招', 在谈数: 0 };
      // 「发布 · AI代理开始寻访」不能发完是个空盘子（标注 2026-08-18 22:31）：
      // 代理立刻匿名接触两名匹配候选，人才页加载完直接看得到东西
      const 起步候选: 候选[] = [
        {
          编号: `${新编号}-N1`,
          岗位编号: 新编号,
          代号: '魏疏桐',
          画像: '7 年 · 核心技能对口 · 在职看机会',
          真名: null,
          头像字: '魏',
          阶段: '匿名初筛',
          轮次: '第 1 轮',
          下一步: 'AI代理已发起匿名接触，等待对方代理响应',
          辅助文案: '硬性条件核对中，无需你介入',
          需要你: false,
          分歧: null,
          匹配分: 88,
        },
        {
          编号: `${新编号}-N2`,
          岗位编号: 新编号,
          代号: '韩沐野',
          画像: '5 年 · 硬性条件全过 · 离职可快速到岗',
          真名: null,
          头像字: '韩',
          阶段: '匿名初筛',
          轮次: '第 1 轮',
          下一步: '薪资带交集核对中',
          辅助文案: '硬性条件核对中，无需你介入',
          需要你: false,
          分歧: null,
          匹配分: 84,
        },
      ];
      return {
        ...旧,
        岗位列表: [新岗, ...旧.岗位列表],
        推荐列表: [
          ...旧.推荐列表,
          ...起步推荐模板.map((模) => ({ ...模, 编号: `${模.编号}@${新编号}`, 岗位编号: 新编号 })),
        ],
        企业候选列表: [...旧.企业候选列表, ...起步候选],
        当前岗位编号: 新编号,
        企业子视图: '在谈',
        企业Tab: '人才',
      };
    }

    // 切身份后落在对应端的主视图：求职者进「职位」，招聘方进「人才」。
    // 两端视角不同，不能停在上一次离开时的 Tab（标注意见 2026-08-18）
    case '切身份':
      return 动作.到 === '求职者'
        ? { ...旧, 当前Tab: '职位', 子视图: '在谈' }
        : { ...旧, 企业Tab: '人才', 企业子视图: '在谈' };

    default:
      return 旧;
  }
}

// ── Backend 水合 / 会话 / 操作 ───────────────────────────────────

// 后端状态与操作组合类型已按 owner 拆到 ./后端/类型；此处保留公开导入路径。
export type { 应用操作, 后端状态 } from './后端/类型';

interface 应用状态值 {
  状态: 状态;
  派发: (动作: 动作) => void;
  数据源模式: 'mock' | 'backend';
  后端状态: 后端状态;
  操作: 应用操作;
  /** 目录查询方法（Task 3 R8）：Backend 模式暴露 查询Location/Taxonomy/Institution，Mock 为 null */
  目录查询: Pick<HTTP招聘数据源, '查询Location' | '查询Taxonomy' | '查询Institution'> | null;
}

const 上下文 = createContext<应用状态值 | null>(null);

export function 应用状态提供者({ children, 数据源 }: { children?: ReactNode; 数据源?: 招聘数据源选择 }) {
  const 源 = 数据源 ?? 招聘数据;
  const 是后端 = 源.模式 === 'backend';
  const 后端 = 是后端 ? 源.后端 : null;
  const 环境 = 源.后端环境 ?? 'stg';
  const [状态, 派发] = useReducer(归约, 源, 创建初始状态);
  const [后端状态, 设后端状态] = useState<后端状态>(() => ({
    初始化: 是后端 ? '进行中' : '跳过',
    已登录: false,
    主体: null,
    简历快照: null,
    意向快照: {},
    岗位快照: {},
    隐私快照: null,
    // P6：Agent 规则域种子全空，双端水合阶段都从 未开始 起跑
    候选规则快照: {},
    招聘规则快照: {},
    候选规则提案: {},
    招聘规则提案: {},
    Agent规则水合: {
      candidate: { rules: '未开始', proposals: '未开始' },
      recruiter: { rules: '未开始', proposals: '未开始' },
    },
    Agent设置: 创建空Agent设置状态(),
    // P4：发现推荐 raw scope 快照/详情/委托回执全部空底座起步（Mock 发现域不触达这里）
    ...创建空P4发现状态(),
    // P5：MatchCase 内存态快照（工作区/历史/详情）空底座起步；绝不进 资料持久化
    ...创建空P5MatchCase状态(),
    // P7：真人会话内存态快照（收件箱/详情/消息页）空底座起步；绝不进 资料持久化
    ...创建空P7会话状态(),
    // P8：账号控制面内存态快照（凭证/会话/导出）空底座起步；绝不进 资料持久化
    ...创建空P8控制面状态(),
    // 接触记录：候选 me/contact-events 内存态分页快照空底座起步；绝不进 资料持久化
    ...创建空接触记录状态(),
    // P2：附件库权威快照种子为 null（Backend 初始不带任何演示附件行）
    附件简历库: null,
    // P0 修复 Task 1：招聘方档案 / 组织链两个水合阶段从 未开始 起跑
    ...创建空招聘方组织水合状态(),
    // 候选 onboarding 预填状态从 pristine inactive 起跑（Backend-only；Mock 不触达）
    候选预填状态: 创建空候选预填状态(),
  }));

  // 让异步操作读到最新的 后端状态 / 状态（useMemo 闭包只捕获首次值）
  const 后端状态引用 = useRef(后端状态);
  后端状态引用.current = 后端状态;
  const 状态引用 = useRef(状态);
  状态引用.current = 状态;
  // 手机登录尝试号：开始登录写入，完成登录读出
  const 尝试引用 = useRef<string | null>(null);
  // StrictMode 下 effect 会跑两次，用 ref 阻止恢复会话重复请求
  const 已初始化 = useRef(false);
  // 并发写锁：简历保存 / 意向:${id|new} 同一操作进行中时拒绝重复提交
  const 锁 = useRef<Set<string>>(new Set());
  // review-r2 R2-I-4：当前主体 subject_id。新主体到达时若 subject_id 变了，
  // 先清上个账号的草稿/快照/缓存，再接受新主体（同 Provider 实例跨账号泄漏）。
  const 主体标识引用 = useRef<string | null>(null);
  // review-r2 R2-M-4：会话代际。登录/退出/401 清理时递增；目录请求捕获起始代际，
  // 401 到达时若代际已变（新会话），stale 401 被忽略，不清新会话。
  const 会话代际 = useRef(0);
  // P4 Task 3：discovery 运行时引用 —— scope 代际 / pending 幂等意图 / 双端可见范围。
  // Provider 一次性初始化；清账号状态 / 登录换主体 / 切身份 时统一复位（会话操作.ts）。
  const P4范围代际 = useRef(new Map<string, number>());
  const P4幂等意图 = useRef(new Map<string, string>());
  const P4可见范围 = useRef<Record<BFF角色, string | null>>({ candidate: null, recruiter: null });
  // P5 Task 3：MatchCase 运行时引用 —— scope 代际 / pending 幂等意图 / 双端可见范围 /
  // 在途 PDF 对象租约。一次性初始化；会话转移由下方主体基串 effect 统一复位。
  const P5范围代际 = useRef(new Map<string, number>());
  const P5幂等意图 = useRef(new Map<string, string>());
  const P5可见范围 = useRef<Record<P5角色, string | null>>({ candidate: null, recruiter: null });
  const P5对象租约 = useRef(new Set<PDF对象租约>());
  // P7 Task 2：真人会话运行时引用 —— scope 代际 / 待定发送意图 / 双端可见收件箱与
  // 可见会话 / 已读位置。一次性初始化；会话转移由下方主体基串 effect 统一复位。
  const P7范围代际 = useRef(new Map<string, number>());
  const P7待定意图 = useRef(new Map<string, P7待定意图>());
  const P7可见收件箱 = useRef<Record<P7角色, boolean>>({ candidate: false, recruiter: false });
  const P7可见会话 = useRef<Record<P7角色, string | null>>({ candidate: null, recruiter: null });
  const P7已读位置 = useRef(new Map<string, P7已读位置记录>());
  // P8 Task 3：账号控制面运行时引用 —— 范围代际 / 账号可见 / 读锁 / 待定意图 /
  // 导出恢复。一次性初始化；会话转移由下方主体（不含角色）effect 与 会话操作 的
  // 清理口统一复位（导出恢复句柄跨登出保留，spec §8.3）。
  const P8范围代际 = useRef(0);
  const P8账号可见 = useRef(false);
  const P8读取锁 = useRef(new Map<'credentials' | 'sessions' | 'export', Promise<void>>());
  const P8待定意图 = useRef(new Map<string, P8待定意图<unknown>>());
  const P8导出恢复 = useRef<P8导出恢复存储 | null>(null);
  // 候选 onboarding 预填运行时引用 —— 预填代际 / exact tuple 单飞读锁 / 恢复元数据适配器。
  // 一次性初始化；会话转移（登出 / 401 / 换主体 / 切离 candidate）由 会话操作 的清理口
  // 与 清候选Onboarding预填 统一复位。
  const 候选预填代际 = useRef(0);
  const 候选预填读取锁 = useRef(new Map<string, Promise<void>>());
  const 候选预填恢复 = useRef<候选预填恢复存储 | null>(null);
  // 接触记录运行时引用 —— 域读代际 / 同 owner 单飞读锁 / 已消费 cursor 集。
  // 一次性初始化；会话转移由下方主体基串 effect 与 会话操作 的清理口统一复位。
  const 接触记录代际 = useRef(0);
  const 接触记录读取锁 = useRef<Promise<void> | null>(null);
  const 接触记录已消费游标 = useRef(new Set<string>());
  const 当前主体标识 = 后端状态.主体?.subject_id ?? null;
  // Task 4：候选 onboarding 草稿只认 candidate 角色 + 当前 subject 的双重范围；
  // recruiter / 未登录 / Mock 一律 null，绝不给持久层授权任何候选草稿读写。
  const 当前候选主体标识 =
    后端状态.主体?.last_used_role === 'candidate'
      ? 后端状态.主体.subject_id
      : null;
  // P8 Task 5：subject 绑定的导出恢复适配器。Backend 主体在场才构造（local 存储 +
  // 模式/环境/账号 三重隔离键）；主体/环境每次变化都在渲染期先写 ref —— 子组件
  // （账号安全页）的被动恢复 effect 一定看到新适配器（或 null），操作方法在调用时
  // 解引用 .current。Mock 恒 null、零存储触碰；绝不把普通适配器捕获进 Provider
  // 生命期的 useMemo。
  P8导出恢复.current = 是后端 && 当前主体标识 !== null
    ? 创建P8导出恢复存储({
      storage: 安全取存储('local'),
      范围: { 模式: 'backend', 环境, 账号: 当前主体标识 },
    })
    : null;
  // 候选 onboarding 预填恢复元数据适配器：candidate 角色强制在构造之前完成 ——
  // 当前候选主体标识 已按 last_used_role==='candidate' 收窄，非候选 scope 绝不交给
  // 存储工厂。Backend + candidate 主体在场才构造（session 存储按 subject 隔离），
  // Mock / 招聘端 / 未登录恒 null、零存储触碰；主体每次变化都在渲染期先写 ref，
  // 操作方法在调用时解引用 .current，绝不把普通适配器捕获进 Provider 生命期的 useMemo。
  候选预填恢复.current = 是后端 && 当前候选主体标识 !== null
    ? 创建候选预填恢复存储({
      // 安全取存储 的运行时值就是完整的 sessionStorage（类型上只收窄成 Pick），可安全视为 Storage
      storage: 安全取存储('session') as Storage | null,
      范围: { 模式: 'backend', 环境, 账号: 当前候选主体标识 },
    })
    : null;
  use资料持久化({ 状态, 派发, 是后端, 环境, 当前主体标识, 当前候选主体标识 });

  // P7 Task 5：同源事件源只建一次（无 token/query/header；帧只触发 no-store 重拉）。
  // 钩子输入全部由 Provider 注入（与 useMatchCase轮询 同一纪律，不读 Context）；
  // 内部按 Backend + 已登录 + 有效角色 + 页面可见开关连接，Mock 零连接。
  const 招聘事件源 = useMemo(() => 创建招聘事件源(), []);

  // P1C：从 subject-scoped sessionStorage 读取恢复的 current relation 候选值。
  // 只作为 选择当前企业关系(affiliations, restoredId) 的输入；读取本身不派发选择 action，
  // revoked ID 只会在最新 Affiliations 校验后被丢弃。
  const 读取恢复企业关系编号 = (subjectId: string): string | null => {
    const 快照 = 读资料缓存(安全取存储('session'), { 模式: 'backend', 环境, 账号: subjectId });
    const 值 = 快照.当前企业关系编号;
    return typeof 值 === 'string' ? 值 : null;
  };

  // ── Backend 初始化：mount 时恢复会话一次；401 视为未登录，其他错误轻提示；均不回退 Mock ──
  // 已知边缘：资源写入的 in-flight 代际守卫未实现（R3-I-1 延后）——但登录水合链（P1C 起）带
  // subject fence + 会话代际：mount/切角色 先写 ref 再水合，组织水合内部逐响应丢弃过时结果。
  useEffect(() => {
    if (!是后端 || !后端) return;
    if (已初始化.current) return;
    已初始化.current = true;
    let 已取消 = false;
    (async () => {
      try {
        await 后端.恢复会话();
      } catch (错误) {
        if (已取消) return;
        if (错误 instanceof BFF错误 && 错误.status === 401) {
          // 401 只清后端状态，不载入 Mock 支持域
          设后端状态((旧) => ({ ...旧, 初始化: '完成', 已登录: false }));
          // Task 2：401 清空目录缓存，避免下个会话复用上个会话的目录页缓存。
          后端?.清空目录缓存();
        } else {
          轻提示(取后端错误文案(错误));
          设后端状态((旧) => ({ ...旧, 初始化: '完成', 已登录: false }));
        }
        return;
      }
      if (已取消) return;
      let 主体: BFF主体;
      try {
        主体 = await 后端.读取主体();
      } catch (错误) {
        if (已取消) return;
        轻提示(取后端错误文案(错误));
        设后端状态((旧) => ({ ...旧, 初始化: '完成', 已登录: false }));
        return;
      }
      if (已取消) return;
      // P1C：读取主体后先建立 subject fence 再开始任何角色水合 —— mount 恢复出一个新会话，
      // 先递增 generation 再把捕获值传入水合；不能在水合完成后才写 ref（否则同一次恢复会话
      // 会被无意义地再次换代，且水合途中无 fence 可拦 stale 响应）。
      主体标识引用.current = 主体.subject_id;
      会话代际.current += 1;
      const 本次代际 = 会话代际.current;
      // P6 Task 4：mount 恢复 = 主体转移 —— 水合前先把规则域重置回干净底座
      //（原始字典/双端阶段清零 + 页面数组清空），保证每次进入水合都跑完整链路，
      // 阶段不可能粘住上个会话残留的 进行中|成功。
      派发({ 型: '清后端Agent规则' });
      // P2 Task 3：mount 恢复 = 主体转移，候选侧附件库快照随 P6 底座一并清空
      // P0 修复 Task 1：招聘方两个水合阶段同口径回底座 —— 上个会话可能停在 缺失|成功|失败，
      // 而新主体若是 candidate / null 角色，水合角色数据 根本不进招聘方分支，没有任何后续写入
      // 会覆盖它们；不在这里复位就会把上个招聘方的 onboarding 判定漏给下一个主体。
      设后端状态((旧) => ({
        ...重置Agent规则后端状态(旧),
        ...创建空招聘方组织水合状态(),
        附件简历库: null,
      }));
      // review-r2 R2-I-3：水合 401 时 水合角色数据 内部已走登出清理并返回 会话失效=true，
      // 不再落 已登录=true（旧实现会把上个会话的快照/草稿留给已失效的登录态）。
      // P7/P8/候选预填引用随行：当前轮 401 的 清账号状态 一并复位五个 P7 引用、
      // 四个 P8 引用与三个候选预填引用。
      const 会话失效 = await 水合角色数据({
        后端, 派发, 设后端状态, 主体标识引用, 会话代际, 读取恢复企业关系编号,
        P4范围代际, P4幂等意图, P4可见范围,
        P7范围代际, P7待定意图, P7可见收件箱, P7可见会话, P7已读位置,
        P8范围代际, P8账号可见, P8读取锁, P8待定意图,
        候选预填代际, 候选预填读取锁, 候选预填恢复,
      }, 主体, false, 本次代际);
      if (已取消) return;
      if (会话失效) {
        // review-r3 R3-I-2：清账号状态 已在 水合角色数据 内部清完（含主体标识 + 会话代际），
        // 初始化 也已随之落成 完成，这里只早退，不再重复清理。
        return;
      }
      // mount 收口前区分三种终局：清理（上面早退）/ 被更新会话取代 / 正常提交。
      // 水合在飞期间完成了新的短信登录（主体或代际已换）时，数据提交已由外层栅栏整包丢弃，
      // 这里只收口 初始化 —— 绝不把过时的主体/登录态写回去覆盖新会话。
      if (
        主体标识引用.current !== 主体.subject_id ||
        会话代际.current !== 本次代际
      ) {
        设后端状态((旧) => 旧.初始化 === '进行中'
          ? { ...旧, 初始化: '完成' }
          : 旧);
        return;
      }
      设后端状态((旧) => ({ ...旧, 初始化: '完成', 已登录: true, 主体 }));
    })();
    return () => {
      已取消 = true;
      // StrictMode 下 dev 会 setup→cleanup→setup：第一次的异步已被 已取消=true 取消，
      // 但 已初始化.current 仍为 true，第二次 setup 会早退 → 初始化永远停在 '进行中'。
      // 这里一并复位 ref，让第二次 setup 重新跑初始化；第一次的异步已被 已取消 守住不会再 set state。
      // 生产环境（无 StrictMode）cleanup 只在 unmount 时跑，复位不影响。
      已初始化.current = false;
    };
    // 是后端 / 后端 在同一 Provider 实例下不变；派发 / 设后端状态 由 React 保证稳定
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [是后端, 后端]);

  // ── P5 Task 3：MatchCase 会话边界的反应式清理 ─────────────────────────────────
  // 登出 / 401 清理 / 换主体登录 / 切身份在状态上全部表现为「主体基串（subject + 角色）」
  // 变化：这里统一清 P5 内存快照、scope 代际与幂等意图引用，并回收全部在途 PDF 对象
  // 租约（内存纪律：P5 状态绝不进 资料持久化 / 浏览器存储；在飞请求由操作层自身的
  // subject/role/会话代际栅栏按旧代整包丢弃）。同主体重登（基串不变）不清 —— 与 P4
  // 草稿保留口径一致，且不确定结果的同键重试跨重登仍可沿用。
  // Backend MatchCase 真相源修复：主体基串变化同时派发 清后端MatchCase演示状态，
  // 四个 legacy 演示数组与 P5 快照同口径归零（Mock 下 主体 恒 null，基串不变，永不派发）。
  // 首个主体到达（'' → 基，mount 恢复 / 登录后的第一个主体）跳过清理：登出 / 401 转移
  //（基 → ''）已经清空过一切，再清只会把同帧子组件刚注册的可见范围拆掉 —— 刷新落在
  // P5 页面时页面与主体同 commit 挂载，子 effect 先于本 effect 执行，这里的清理会让
  // 刚发出的首个读取被栅栏整包丢弃，无轮询的页面（「我的」）将永远停在缺失态。
  const P5会话基 = useRef('');
  useEffect(() => {
    const 基 = 后端状态.主体 === null ? '' : `${后端状态.主体.subject_id}|${后端状态.主体.last_used_role}`;
    if (P5会话基.current === 基) return;
    const 首个主体到达 = P5会话基.current === '';
    P5会话基.current = 基;
    if (首个主体到达) return;
    清P5MatchCase引用({ P5范围代际, P5幂等意图, P5可见范围, P5对象租约 });
    设后端状态((旧) => ({ ...旧, ...创建空P5MatchCase状态() }));
    派发({ 型: '清后端MatchCase演示状态' });
    // 主体 每次替换都是新对象；设后端状态 由 React 保证稳定
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [后端状态.主体]);

  // ── P7 Task 2：真人会话会话边界的反应式清理 ─────────────────────────────────
  // 与 P5 同一主体基串口径：登出 / 401 清理 / 换主体登录 / 切身份在状态上全部表现为
  // 「主体基串（subject + 角色）」变化。这里统一清 P7 内存快照与五个引用（范围代际 /
  // 待定发送意图 / 双端可见收件箱与可见会话 / 已读位置），在飞请求由操作层自身的
  // subject/role/会话代际栅栏按旧代整包丢弃。同主体重登（基串不变）不清。
  const P7会话基 = useRef('');
  useEffect(() => {
    const 基 = 后端状态.主体 === null ? '' : `${后端状态.主体.subject_id}|${后端状态.主体.last_used_role}`;
    if (P7会话基.current === 基) return;
    P7会话基.current = 基;
    清P7会话引用({ P7范围代际, P7待定意图, P7可见收件箱, P7可见会话, P7已读位置 });
    设后端状态((旧) => ({ ...旧, ...创建空P7会话状态() }));
    // 主体 每次替换都是新对象；设后端状态 由 React 保证稳定
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [后端状态.主体]);

  // ── 接触记录会话边界的反应式清理 ─────────────────────────────────────────────
  // 与 P5 同一主体基串口径：登出 / 401 清理 / 换主体登录 / 切身份（离开 candidate 角色）
  // 在状态上全部表现为「主体基串（subject + 角色）」变化。这里统一清接触事件快照、
  // 域读代际、单飞读锁与已消费 cursor 集（内存纪律：绝不进 资料持久化 / 浏览器存储；
  // 在飞请求由操作层自身的 subject/role/会话代际/域代际栅栏按旧代整包丢弃）。
  // 首个主体到达（'' → 基）跳过清理：登出 / 401 转移（基 → ''）已经清空过一切，
  // 再清只会把同帧子组件（「谁接触过我」页）刚发出的首载按域代际整包丢弃 ——
  // 刷新落在该页时页面与主体同 commit 挂载，子 effect 先于本 effect 执行
  //（与 P5 d82de7d6 同一竞态，语义照搬）。
  const 接触记录会话基 = useRef('');
  useEffect(() => {
    const 基 = 后端状态.主体 === null ? '' : `${后端状态.主体.subject_id}|${后端状态.主体.last_used_role}`;
    if (接触记录会话基.current === 基) return;
    const 首个主体到达 = 接触记录会话基.current === '';
    接触记录会话基.current = 基;
    if (首个主体到达) return;
    清接触记录引用({ 接触记录代际, 接触记录读取锁, 接触记录已消费游标 });
    设后端状态((旧) => ({ ...旧, ...创建空接触记录状态() }));
    // 主体 每次替换都是新对象；设后端状态 由 React 保证稳定
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [后端状态.主体]);

  // ── P8 Task 3：账号控制面会话边界的反应式清理 ─────────────────────────────────
  // 与 P5/P7 不同，P8 的清理键只认主体（账号资源以 subject 为隔离边界，不按
  // candidate/recruiter 重复保存）：登出 / 401 清理 / 换主体登录在状态上表现为
  // 「主体基串」变化，这里清三块账号快照并复位四个引用；同主体切角色基串不变，
  // 已确认快照保留（切身份 里的显式栅栏递增负责作废上个角色的在飞读写）。
  const P8会话基 = useRef('');
  useEffect(() => {
    const 基 = 后端状态.主体 === null ? '' : 后端状态.主体.subject_id;
    if (P8会话基.current === 基) return;
    P8会话基.current = 基;
    清P8控制面引用({ P8范围代际, P8账号可见, P8读取锁, P8待定意图 });
    设后端状态((旧) => ({ ...旧, ...创建空P8控制面状态() }));
    // 主体 每次替换都是新对象；设后端状态 由 React 保证稳定
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [后端状态.主体]);

  const 操作 = useMemo<应用操作>(
    () => {
      const deps: 后端操作依赖 = {
        是后端,
        后端,
        派发,
        设后端状态,
        后端状态引用,
        状态引用,
        锁,
        尝试引用,
        主体标识引用,
        会话代际,
        读取恢复企业关系编号,
        P4范围代际,
        P4幂等意图,
        P4可见范围,
        P5范围代际,
        P5幂等意图,
        P5可见范围,
        P5对象租约,
        P7范围代际,
        P7待定意图,
        P7可见收件箱,
        P7可见会话,
        P7已读位置,
        P8范围代际,
        P8账号可见,
        P8读取锁,
        P8待定意图,
        P8导出恢复,
        候选预填代际,
        候选预填读取锁,
        候选预填恢复,
        接触记录代际,
        接触记录读取锁,
        接触记录已消费游标,
      };
      return {
        ...创建会话操作(deps),
        ...创建候选操作(deps),
        ...创建岗位操作(deps),
        ...创建组织操作(deps),
        ...创建隐私操作(deps),
        // P6：Agent 规则/提案操作与其它域共用同一把 deps（锁 / 主体标识 / 会话代际）
        ...创建Agent规则操作(deps),
        // P4 Task 3：发现推荐读操作（scope 注册 + 栅栏化读取），同一把 deps
        ...创建发现推荐操作(deps),
        // P2：附件简历操作同样共用同一把 deps（库锁/文件锁落在同一把 锁 里）
        ...创建附件简历操作(deps),
        // P5 Task 3：MatchCase 操作（内存态快照 + 意图键化命令 + 租约），同一把 deps
        ...创建MatchCase操作(deps),
        // P7 Task 2：真人会话操作（内存态快照 + 意图键化发送对账 + forward-only 已读），同一把 deps
        ...创建真人会话操作(deps),
        // P8 Task 3+5：账号控制面操作（内存态快照 + 单飞读取 + 意图键化换绑/退出其他
        // 设备 + 导出恢复/创建/刷新/废弃/下载地址 + 账号注销），同一把 deps；
        // 导出恢复适配器由上方渲染期按主体换绑；Task 6+7 合规两法（反馈 + 上下文举报）
        // 同在此工厂返回
        ...创建P8账号安全操作(deps),
        // 候选 onboarding 简历预填操作（栅栏化单飞读取 + 恢复/激活/同步/重试/手填/确认/
        // 清理），同一把 deps；恢复元数据适配器由上方渲染期按 candidate 主体换绑
        ...创建简历预填操作(deps),
        // JD PDF 建议稿导入操作（consent 后创建 + 轮询读取，主体/角色/会话栅栏化），
        // 同一把 deps；导入运行态留在 发布岗位 页面本地
        ...创建JD导入操作(deps),
        // 接触记录操作（候选「谁接触过我」首载/刷新/分页追加，栅栏化单飞），同一把 deps
        ...创建接触记录操作(deps),
      };
    },
    // 是后端 / 后端 在同一 Provider 实例下不变；派发 / 设后端状态 由 React 保证稳定
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [是后端, 后端],
  );

  // ── P6 页面数组派生：raw 快照（或权威意向字典）任一变化都重算分组 ──
  // Rule 请求与 Intention 请求谁先完成都不影响最终归属：这里只吃 raw 输入，
  // orphan 意向 scope 在权威意向到达前整条省略，到达后同一 raw Rule 自动归组。
  // 意向侧读 状态.后端意向服务端（水合后端意向 落的权威字典，操作与会话层双写），
  // 与 候选分组 的其余消费者同源，避免再养第二份意向真相。
  useEffect(() => {
    if (!是后端 || 后端状态.Agent规则水合.candidate.rules !== '成功') return;
    const mapped = 映射候选Agent规则(
      Object.values(后端状态.候选规则快照),
      状态.后端意向服务端,
    );
    派发({ 型: '水合后端候选规则', 全局: mapped.全局, 意向级: mapped.意向级 });
  }, [是后端, 后端状态.Agent规则水合.candidate.rules, 后端状态.候选规则快照, 状态.后端意向服务端]);

  useEffect(() => {
    if (!是后端 || 后端状态.Agent规则水合.recruiter.rules !== '成功') return;
    派发({
      型: '水合后端招聘规则',
      规则: 映射招聘Agent规则(Object.values(后端状态.招聘规则快照)),
    });
  }, [是后端, 后端状态.Agent规则水合.recruiter.rules, 后端状态.招聘规则快照]);

  use真人会话事件({
    事件源: 招聘事件源,
    可见会话引用: P7可见会话,
    数据源模式: 源.模式,
    已登录: 后端状态.已登录,
    角色: (后端状态.主体?.last_used_role ?? null) as P7角色 | null,
    操作,
  });

  // 目录查询 seam 已按 owner 拆到 ./后端/目录查询：Backend 模式暴露 查询Location/Taxonomy/Institution，
  // Mock 为 null；401 会话代际守卫与统一清理都在 创建目录查询 内部。
  // useMemo 键 是后端/后端（同 Provider 实例下不变），使 目录查询 引用稳定。
  const 目录查询 = useMemo(
    () => 创建目录查询({
      是后端, 后端, 派发, 设后端状态, 主体标识引用, 会话代际,
      P4范围代际, P4幂等意图, P4可见范围,
      // codex review-r1 P2：目录 401 的统一清理随行候选预填引用（同账号重登不复活旧轮）
      候选预填代际, 候选预填读取锁, 候选预填恢复,
    }),
    // 是后端 / 后端 在同一 Provider 实例下不变；派发 / 设后端状态 由 React 保证稳定
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [是后端, 后端],
  );

  const 值 = useMemo<应用状态值>(
    () => ({ 状态, 派发, 数据源模式: 源.模式, 后端状态, 操作, 目录查询 }),
    [状态, 派发, 源.模式, 后端状态, 操作, 目录查询],
  );
  return <上下文.Provider value={值}>{children}</上下文.Provider>;
}

export function use应用状态() {
  const 值 = useContext(上下文);
  if (!值) throw new Error('use应用状态 必须在 应用状态提供者 内部使用');
  return 值;
}
